solution.javascript:
function lastStoneWeight(stones) {
  const heap = stones.slice().sort((a,b) => b - a);
  while (heap.length > 1) {
    const y = heap.shift(), x = heap.shift();
    const diff = y - x;
    if (diff > 0) {
      let i = 0; while (i < heap.length && heap[i] > diff) i++;
      heap.splice(i, 0, diff);
    }
  }
  return heap[0] ?? 0;
}

solution.cpp:
int lastStoneWeight(vector<int>& stones) {
    priority_queue<int> pq(stones.begin(), stones.end());
    while (pq.size() > 1) {
        int y = pq.top(); pq.pop();
        int x = pq.top(); pq.pop();
        if (y > x) pq.push(y - x);
    }
    return pq.empty() ? 0 : pq.top();
}
